=== appsettings.json ===
{
  "Serilog": {
    "Using":  [ "Serilog.Sinks.File" ],
    "MinimumLevel": {
      "Default": "Information",
      "Override": {
        "Microsoft.AspNetCore": "Information",
        "Microsoft.EntityFrameworkCore": "Warning",
        "System.Net.Http": "Warning"
      }
    },
    "WriteTo": [
      { 
        "Name": "File",
        "Args": {
          "path": "Logs/log-.txt",
          "rollingInterval": "Day",
          "retainedFileCountLimit": "60"
        }
      }
    ]
  },
  "Logging": {
    "LogLevel": {
      "Default": "Information",
      "Microsoft.AspNetCore": "Warning"
    }
  },
  "KeycloakUserSettings": {
    "ClientName": "strassennamen"
  },
  "ConnectionStrings": {
    "DB": ""
  },
  "CorsOrigins": [],
  "UserServiceSettings": {
    "KeycloakBaseUrl": "",
    "Realm": "",
    "ClientId": "",
    "ClientSecret": "",
    "KeycloakLoginPath": ""
  },
  "Jobs": {
    "Heartbeat": {
      "Active": true,
      "CronSchedule": "0 0/5 * 1/1 * ? *"
    },
    "XmlExportStrassen": {
      "Active": false,
      "CronSchedule": "0 0 1 1/1 * ? *",
      "FilePath": null,
      "FilterStrassenStatus": "Aktiv"
    }
  }
}

